from solution import find_lists


def test_issue_example_two_lists():
    """Example: find_lists(([1,2,3,4],[5,6,7,8])) == 2."""
    assert find_lists(([1, 2, 3, 4], [5, 6, 7, 8])) == 2  # 1 + 1 = 2


def test_issue_empty_tuple():
    """Empty tuple has number of lists present 0."""
    assert find_lists(()) == 0  # 0 + 0 = 0


def test_issue_no_lists():
    """Tuple with no lists has count 0."""
    assert find_lists((1, 2, "a", (3, 4))) == 0  # 0 + 0 = 0


def test_issue_single_list():
    """One list among scalars counts as 1."""
    assert find_lists(([1, 2, 3], 1, 2)) == 1  # 1 + 0 = 1


def test_issue_three_lists():
    """Three lists give count 3."""
    assert find_lists(([1], [2], [3])) == 3  # 1 + 1 + 1 = 3


def test_issue_five_lists():
    """Five lists give count 5."""
    assert find_lists(([1], [2], [3], [4], [5])) == 5  # 1 + 1 + 1 + 1 + 1 = 5


def test_issue_empty_lists_counted():
    """Empty lists are still lists and are counted."""
    assert find_lists(([], [], 1, ())) == 2  # 1 + 1 = 2


def test_issue_nested_lists_count_once():
    """Only top-level lists present in the tuple are counted."""
    assert find_lists(([[1, 2], [3, 4]], "x", 5)) == 1  # 1 + 0 = 1


def test_issue_scalars_and_none_not_counted():
    """Ints, floats and None are not lists."""
    assert find_lists(([9], 1, 2.5, None, 0)) == 1  # 1 + 0 = 1


def test_contract_tuples_not_counted():
    """Only lists count, so tuples present are not counted."""
    assert find_lists(([1], (2, 3), (4, 5))) == 1  # 1 + 0 + 0 = 1


def test_contract_strings_dicts_sets_not_counted():
    """Only lists count, so strings, dicts and sets are not counted."""
    assert find_lists(([1, 2], "abc", {"a": 1}, {1, 2})) == 1  # 1 + 0 + 0 + 0 = 1
